            )?;
        }
        for pattern in &self.patterns {
            control
                .charge(WorkKind::PaintVisit, 1)
                .map_err(crate::types::stopped)?;
            total = add(total, pattern.tile.allocated_byte_count())?;
        }
        Ok(total)
